<script setup lang="ts">
import type {DhcpConfig,DhcpInterface} from '../tools/dhcp'
const p=defineProps<{en:boolean;config:DhcpConfig;interfaces:DhcpInterface[];disabled:boolean;running:boolean}>(),emit=defineEmits<{run:[];stop:[]}>()
const t=(a:string,b:string)=>p.en?b:a
</script>
<template><div class="dhcp-setup"><h2>{{t('DHCPv4 诊断','DHCPv4 diagnostics')}}</h2>
<p>{{t('只读检查本机配置；主动发现只发送 DISCOVER，不续租、释放或修改地址。','Inspect local configuration; discovery sends DISCOVER only, without renewing, releasing or changing addresses.')}}</p>
<div class="form-grid"><label>{{t('操作','Operation')}}<select id="dhcp-operation" v-model="config.operation"><option value="inspect">{{t('只读配置检查','Inspect configuration')}}</option><option value="discover">{{t('主动发现服务器','Discover servers')}}</option></select></label>
<label>{{t('接口 ID / 名称 / 索引','Interface ID / name / index')}}<input id="dhcp-interface" v-model="config.interface" list="dhcp-interfaces" :placeholder="t('检查可留空；发现必须指定','Optional for inspection; required for discovery')"><datalist id="dhcp-interfaces"><option v-for="i in interfaces" :key="i.id" :value="i.id">{{i.name}} [{{i.index}}]</option></datalist></label>
<template v-if="config.operation==='discover'"><label>{{t('收集窗口（秒，1–30）','Collection window (seconds, 1–30)')}}<input id="dhcp-duration" type="number" min="1" max="30" v-model.number="config.duration_secs"></label><label>{{t('DISCOVER 次数（1–3）','DISCOVER attempts (1–3)')}}<input id="dhcp-attempts" type="number" min="1" max="3" v-model.number="config.attempts"></label>
<label class="wide">{{t('预期服务器 IPv4（可选，逗号分隔）','Expected server IPv4 addresses (optional, comma separated)')}}<input id="dhcp-expected" :value="config.expected_servers.join(', ')" @input="config.expected_servers=($event.target as HTMLInputElement).value.split(/[,\s]+/).filter(Boolean)"></label></template></div>
<p v-if="config.operation==='discover'" class="dhcp-note">{{t('先运行只读检查，再选择接口。使用标准 UDP 68→67；出站源 IP 由指定接口的系统栈选择（未配置地址的接口待验收）。端口被占用或权限不足会明确失败，请勿停止系统 DHCP 客户端。DISCOVER 可能临时预留 Offer 地址；多服务器可合法，清单外不代表恶意。','Run inspection first, then select an interface. Uses standard UDP 68→67; the pinned interface supplies the source IP (unconfigured interfaces await acceptance). port conflicts or missing privileges fail explicitly. Keep the system DHCP client running. DISCOVER may temporarily reserve an offer; multiple servers can be legitimate, and outside-list does not imply malicious.')}}</p>
<div class="actions"><button class="primary" :disabled="disabled||(config.operation==='discover'&&!config.interface.trim())" @click="emit('run')">{{t('开始 DHCP 诊断','Run DHCP diagnostics')}}</button><button v-if="running" @click="emit('stop')">{{t('停止并保留结果','Stop and retain results')}}</button></div></div></template>
<style scoped>.dhcp-setup{min-width:0;padding:20px;box-sizing:border-box}.dhcp-note{padding:10px;background:var(--surface-soft);border-radius:8px}.form-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.wide{grid-column:1/-1}label{display:flex;flex-direction:column;gap:6px}input,select{min-width:0;width:100%;box-sizing:border-box}.actions{display:flex;gap:8px;flex-wrap:wrap;margin-top:16px}</style>
